# Generated by manage.py generate_test_cases.
from django.contrib.contenttypes.models import ContentType
from django.urls import reverse
from playwright.sync_api import Locator, expect

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.users.user_list_view_preference import UserListViewPreference
from bloomerp.models.workspaces.tile import Tile
from bloomerp.models.workspaces.workspace import Workspace
from bloomerp.tests.base import (
    BloomerpE2ETestCase,
    E2EAction,
    E2ERequestScenario,
)
from bloomerp.utils.models import get_list_view_url
from bloomerp.workspaces.dataview_tile.model import DataViewTileConfig


class TestBloomerpModuleWorkspaceViewE2E(BloomerpE2ETestCase):
    """Keep workspace data-view loading and card clicks from stealing focus."""

    view_name = "workspace"
    auto_create_customers = False
    browser_context_options = {"viewport": {"width": 1280, "height": 720}}

    def create_workspace_fixtures(self) -> None:
        """Create a real, taller-than-viewport Kanban in the isolated test DB."""
        for index in range(24):
            self.CustomerModel.objects.create(
                first_name=f"Board row {index:02d}",
                last_name="Example",
                age=30,
            )
        self.target_customer = self.CustomerModel.objects.create(
            first_name="Focus target",
            last_name="Example",
            age=30,
        )
        self.content_type = ContentType.objects.get_for_model(self.CustomerModel)
        last_name = ApplicationField.get_by_field(self.CustomerModel, "last_name")
        preference = UserListViewPreference.objects.create(
            user=self.admin_user,
            content_type=self.content_type,
            name="Workspace focus regression",
            selected=True,
            view_type="kanban",
            split_view_enabled=False,
            display_fields={"kanban": [last_name.pk]},
            options={
                "kanban": {
                    "group_by_field": "age",
                    "page_size": 25,
                    "sort_field": "first_name",
                    "sort_direction": "asc",
                },
            },
        )
        config = DataViewTileConfig(
            content_type_id=self.content_type.pk,
            list_view_preference_id=preference.pk,
            actions=[],
        )
        self.tile = Tile.objects.create(
            name="Tall customer board",
            type="DATAVIEW_TILE",
            schema=config.model_dump(mode="json"),
        )
        self.workspace = Workspace.objects.create(
            name="Workspace focus regression",
            user=self.admin_user,
            layout={
                "rows": [{
                    "columns": 1,
                    "items": [{"id": str(self.tile.pk), "colspan": 1}],
                }],
            },
        )

    def workspace_tile(self) -> Locator:
        """Return the rendered fixture tile, including after an HTMX replacement."""
        return self.page.locator(
            '[bloomerp-component="workspace-tile"]'
            f'[data-layout-item-id="{self.tile.pk}"]'
        )

    def workspace_search(self) -> Locator:
        """Return only the search input inside the fixture's data-view tile."""
        return self.workspace_tile().locator(
            f"#data-view-search-input-{self.content_type.pk}"
        )

    def wait_for_workspace_board(self) -> None:
        """Wait for actual tile rendering and JavaScript component initialization."""
        tile = self.workspace_tile()
        expect(tile.locator('[bloomerp-component="kanban-card"]')).to_have_count(25)
        expect(tile.locator('[bloomerp-component="dataview-container"]')).to_have_attribute(
            "data-component-initialized", "true"
        )
        expect(tile.locator('[bloomerp-component="kanban-board"]')).to_have_attribute(
            "data-component-initialized", "true"
        )
        expect(self.workspace_search()).to_be_visible()

    def assert_workspace_search_unfocused(self) -> None:
        """Check that initializing an embedded data view leaves its search unfocused."""
        expect(self.workspace_search()).not_to_be_focused()

    def reload_workspace_tiles(self) -> None:
        """Apply empty workspace filters through the UI to replace the complete tile."""
        old_search = self.workspace_search().element_handle()
        self.assertIsNotNone(old_search)
        workspace = self.page.locator('[bloomerp-component="workspace-container"]')
        render_url = workspace.get_attribute("data-layout-render-item-url")
        self.assertIsNotNone(render_url)
        workspace.locator("[data-layout-header-section]").get_by_role(
            "button", name="Filter", exact=True
        ).click()
        editor = self.page.locator(
            '[bloomerp-component="unified-filter-container"][data-scope="workspace"]'
        )
        editor.get_by_role("button", name="Clear", exact=True).click()
        with self.expect_response_for(render_url, method="GET") as response_info:
            editor.get_by_role("button", name="Apply", exact=True).click()
        self.assertEqual(response_info.value.status, 200)
        self.page.wait_for_function("element => !element.isConnected", arg=old_search)
        self.wait_for_workspace_board()
        self.assert_workspace_search_unfocused()
        self.page.keyboard.press("Escape")

    def search_workspace_manually(self) -> None:
        """Explicitly focus and use the embedded search to filter real customer cards."""
        search = self.workspace_search()
        search.click()
        expect(search).to_be_focused()
        data_view_url = reverse(
            "components_dataview", kwargs={"content_type_id": self.content_type.pk}
        )
        with self.expect_response_for(data_view_url, method="GET") as response_info:
            search.fill("Focus target")
        self.assertEqual(response_info.value.status, 200)
        cards = self.workspace_tile().locator('[bloomerp-component="kanban-card"]')
        expect(cards).to_have_count(1)
        expect(cards).to_have_attribute("data-object-id", str(self.target_customer.pk))
        expect(search).to_have_value("Focus target")
        expect(search).to_be_focused()

    def scroll_offsets(self, card: Locator) -> list[list[float]]:
        """Read every card ancestor's scroll position without moving or focusing it."""
        return card.evaluate(
            """card => {
                const offsets = [];
                for (let element = card.parentElement; element; element = element.parentElement) {
                    offsets.push([element.scrollLeft, element.scrollTop]);
                }
                return offsets;
            }"""
        )

    def click_scrolled_card_and_open_detail(self) -> None:
        """Keep the first click stable so a double-click at that point opens its card."""
        tile = self.workspace_tile()
        board = tile.locator('[bloomerp-component="kanban-board"]')
        card = board.locator(
            '[bloomerp-component="kanban-card"]'
            f'[data-object-id="{self.target_customer.pk}"]'
        )
        card.scroll_into_view_if_needed()
        title = card.get_by_text(str(self.target_customer), exact=True)
        title_box = title.bounding_box()
        self.assertIsNotNone(title_box)
        click_x = title_box["x"] + title_box["width"] / 2
        click_y = title_box["y"] + title_box["height"] / 2
        offsets_before = self.scroll_offsets(card)
        self.assertTrue(
            any(top > 100 for _, top in offsets_before),
            "The fixture must scroll before testing the tall-board regression.",
        )
        self.assertGreater(board.evaluate("element => element.scrollHeight"), 720)

        # Mouse coordinates deliberately avoid locator.click/dblclick auto-scroll,
        # which could move the card back under the pointer and conceal the bug.
        self.page.mouse.click(click_x, click_y)
        expect(board).to_be_focused()
        expect(tile).not_to_be_focused()
        expect(self.workspace_search()).not_to_be_focused()
        self.assertEqual(self.scroll_offsets(card), offsets_before)
        title_box_after = title.bounding_box()
        self.assertIsNotNone(title_box_after)
        self.assertAlmostEqual(title_box_after["x"], title_box["x"], delta=1)
        self.assertAlmostEqual(title_box_after["y"], title_box["y"], delta=1)

        detail_url = self.target_customer.get_absolute_url()
        with self.expect_response_for(detail_url, method="GET") as response_info:
            self.page.mouse.dblclick(click_x, click_y)
        self.assertEqual(response_info.value.status, 200)
        expect(self.page).to_have_url(self.url(detail_url))
        expect(self.page.locator("#main-content [data-object-pk]")).to_have_attribute(
            "data-object-pk", str(self.target_customer.pk)
        )

    def assert_standalone_search_focused(self) -> None:
        """Preserve automatic search focus on the ordinary standalone model list."""
        expect(self.page.locator('[bloomerp-component="workspace-tile"]')).to_have_count(0)
        expect(self.page.locator('[bloomerp-component="kanban-card"]')).to_have_count(25)
        expect(self.page.locator(
            f"#data-view-search-input-{self.content_type.pk}"
        )).to_be_focused()

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Exercise workspace load, reload, manual search, card navigation and standalone focus."""
        self.create_workspace_fixtures()
        return [
            E2ERequestScenario(
                name="Workspace data-view search focuses only on user request",
                user=self.admin_user,
                url=self.workspace.get_absolute_url(),
                actions=[
                    E2EAction(
                        name="Initial tile loading does not autofocus search",
                        execute=self.wait_for_workspace_board,
                        validators=self.assert_workspace_search_unfocused,
                    ),
                    E2EAction(
                        name="Filter-driven tile replacement does not autofocus search",
                        execute=self.reload_workspace_tiles,
                    ),
                    E2EAction(
                        name="Manual search stays focused and filters customers",
                        execute=self.search_workspace_manually,
                    ),
                ],
            ),
            E2ERequestScenario(
                name="A first click on a tall Kanban keeps the intended double-click target",
                user=self.admin_user,
                url=self.workspace.get_absolute_url(),
                actions=[
                    E2EAction(
                        name="Wait for the real workspace Kanban",
                        execute=self.wait_for_workspace_board,
                    ),
                    E2EAction(
                        name="Keep focus and scroll stable, then open the clicked customer",
                        execute=self.click_scrolled_card_and_open_detail,
                    ),
                ],
            ),
            E2ERequestScenario(
                name="Standalone model data views still autofocus search",
                user=self.admin_user,
                url=reverse(get_list_view_url(self.CustomerModel)),
                actions=[
                    E2EAction(
                        name="Standalone initial load focuses search",
                        execute=self.assert_standalone_search_focused,
                    ),
                    self.page_refresh(validators=self.assert_standalone_search_focused),
                ],
            ),
        ]
